"""
Cohere Transcribe (transformers CohereAsrForConditionalGeneration).

Catalog: cohere-transcribe-03-2026 (14 langs; strong EN; no native timestamps).
Long media is windowed; cues are sentence/length-distributed across each window.
Language must be explicit (ISO); ``auto`` defaults to ``en``.
"""

from __future__ import annotations

import logging
import re
import shutil
import tempfile
import threading
from pathlib import Path
from typing import Any, Callable

from ..download import is_model_installed, model_local_path
from ..progress import asr_local_from_timeline, format_mmss

ProgressCb = Callable[[dict[str, Any]], None]
CueCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.asr.cohere_transcribe")

_MODEL_CACHE: dict[str, Any] = {}
_MODEL_LOCK = threading.Lock()

_WINDOW_S = 30.0
_OVERLAP_S = 0.75
_MAX_CUE_S = 6.5
_TARGET_CUE_CHARS = 28
_SENTENCE_SPLIT_RE = re.compile(r"(?<=[。！？!?．.｡…])")

# Official processor expects ISO-ish language codes among the 14 supported.
_LANG_ALIASES = {
    "jp": "ja",
    "jpn": "ja",
    "cn": "zh",
    "zho": "zh",
    "chi": "zh",
    "cmn": "zh",
    "yue": "zh",
    "kor": "ko",
    "eng": "en",
    "deu": "de",
    "ger": "de",
    "fra": "fr",
    "fre": "fr",
    "spa": "es",
    "ita": "it",
    "por": "pt",
    "nld": "nl",
    "dut": "nl",
    "pol": "pl",
    "ell": "el",
    "gre": "el",
    "vie": "vi",
    "ara": "ar",
}
_SUPPORTED_LANGS = frozenset(
    {
        "en",
        "ja",
        "zh",
        "ko",
        "de",
        "fr",
        "es",
        "it",
        "pt",
        "nl",
        "pl",
        "el",
        "vi",
        "ar",
    }
)


def clear_model_cache() -> int:
    with _MODEL_LOCK:
        n = len(_MODEL_CACHE)
        _MODEL_CACHE.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    return n


def _map_language(language: str | None) -> str:
    """Return ISO language code for the processor; default ``en`` when auto/unknown."""
    raw = str(language or "auto").strip().lower().replace("_", "-")
    if not raw or raw in ("auto", "unknown", "und"):
        return "en"
    base = raw.split("-", 1)[0]
    base = _LANG_ALIASES.get(base, base)
    if base in _SUPPORTED_LANGS:
        return base
    return "en"


def _device_map(device: str) -> str:
    d = str(device or "auto").strip().lower()
    if d == "cpu":
        return "cpu"
    try:
        import torch

        if torch.cuda.is_available() and d in ("auto", "cuda"):
            return "cuda:0"
    except Exception:
        pass
    return "cpu"


def _get_asr_bundle(asr_dir: Path, device: str) -> tuple[Any, Any]:
    import torch

    try:
        from transformers import AutoProcessor, CohereAsrForConditionalGeneration
    except ImportError as err:
        raise RuntimeError(
            "Cohere Transcribe 需要 transformers>=5.6（含 CohereAsrForConditionalGeneration）。"
            "请重新下载/修复该模型依赖，或在引擎 runtime 执行："
            "pip install \"transformers>=5.6.0,<6\" \"tokenizers>=0.22.0,<=0.23.0\"。"
            f" 原始错误: {err}"
        ) from err

    device_map = _device_map(device)
    dtype = torch.bfloat16 if device_map.startswith("cuda") else torch.float32
    key = f"{asr_dir}|{device_map}|{dtype}"
    with _MODEL_LOCK:
        cached = _MODEL_CACHE.get(key)
        if cached is not None:
            return cached
        try:
            processor = AutoProcessor.from_pretrained(str(asr_dir))
            model = CohereAsrForConditionalGeneration.from_pretrained(
                str(asr_dir),
                torch_dtype=dtype,
                device_map=device_map,
            )
        except Exception as err:
            msg = str(err)
            if "Unrecognized processing class" in msg or "Can't instantiate a processor" in msg:
                raise RuntimeError(
                    f"Cohere 模型目录不完整（{asr_dir}）：缺少 processor/tokenizer 配置。"
                    "请对 cohere-transcribe-03-2026 强制重新下载"
                    "（设置中填写 HF Token，镜像建议点「官方」）。"
                    f" 原始错误: {err}"
                ) from err
            raise
        bundle = (processor, model)
        _MODEL_CACHE[key] = bundle
        return bundle


def _probe_duration_s(media_path: str) -> float:
    try:
        from .whisper_fw import _probe_duration_s as probe

        return float(probe(media_path) or 0)
    except Exception:
        return 0.0


def _windows(duration_s: float) -> list[tuple[float, float]]:
    if duration_s <= _WINDOW_S + 1.0:
        return [(0.0, max(duration_s, 0.1))]
    out: list[tuple[float, float]] = []
    cursor = 0.0
    step = max(8.0, _WINDOW_S - _OVERLAP_S)
    while cursor < duration_s - 0.05:
        end = min(duration_s, cursor + _WINDOW_S)
        out.append((cursor, end))
        if end >= duration_s - 0.05:
            break
        cursor += step
    return out or [(0.0, max(duration_s, 0.1))]


def _split_sentences(text: str) -> list[str]:
    raw = str(text or "").strip()
    if not raw:
        return []
    parts = [p.strip() for p in _SENTENCE_SPLIT_RE.split(raw) if p and p.strip()]
    if len(parts) <= 1 and len(raw) > _TARGET_CUE_CHARS * 2:
        chunk = _TARGET_CUE_CHARS
        parts = [raw[i : i + chunk].strip() for i in range(0, len(raw), chunk)]
        parts = [p for p in parts if p]
    return parts or [raw]


def _distribute_text_cues(
    text: str,
    *,
    start: float,
    end: float,
) -> list[dict[str, Any]]:
    parts = _split_sentences(text)
    if not parts:
        return []
    span = max(0.35, float(end) - float(start))
    weights = [max(1, len(p)) for p in parts]
    total_w = float(sum(weights))
    cues: list[dict[str, Any]] = []
    cursor = float(start)
    for i, (part, w) in enumerate(zip(parts, weights)):
        frac = w / total_w
        dur = span * frac
        if i == len(parts) - 1:
            cue_end = float(end)
        else:
            cue_end = min(float(end), cursor + max(0.35, dur))
        cue_end = max(cue_end, cursor + 0.25)
        cues.append(
            {
                "start": cursor,
                "end": min(cue_end, cursor + _MAX_CUE_S * 2),
                "text": part,
            }
        )
        cursor = cue_end
    return cues


def _load_wav_mono_16k(wav_path: str) -> Any:
    """Load mono float waveform at 16 kHz for the Cohere processor."""
    try:
        from transformers.audio_utils import load_audio

        return load_audio(wav_path, sampling_rate=16000)
    except Exception:
        import numpy as np
        import soundfile as sf

        audio, sr = sf.read(wav_path, always_2d=False)
        if getattr(audio, "ndim", 1) > 1:
            audio = np.mean(audio, axis=-1)
        audio = np.asarray(audio, dtype=np.float32)
        if int(sr) != 16000:
            import librosa

            audio = librosa.resample(audio, orig_sr=int(sr), target_sr=16000)
        return audio


def _transcribe_window(
    processor: Any,
    model: Any,
    wav_path: str,
    *,
    language: str,
) -> str:
    import torch

    audio = _load_wav_mono_16k(wav_path)
    inputs = processor(
        audio,
        sampling_rate=16000,
        return_tensors="pt",
        language=language,
    )
    device = getattr(model, "device", None)
    dtype = getattr(model, "dtype", None)
    if device is not None:
        try:
            if dtype is not None:
                inputs = inputs.to(device, dtype=dtype)
            else:
                inputs = inputs.to(device)
        except Exception:
            # BatchEncoding.to may not accept dtype on all transformers builds.
            inputs = inputs.to(device)
    with torch.inference_mode():
        outputs = model.generate(**inputs, max_new_tokens=256)
    text = processor.decode(outputs, skip_special_tokens=True)
    if isinstance(text, list):
        text = text[0] if text else ""
    return str(text or "").strip()


def cohere_transcribe(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "cohere-transcribe-03-2026",
    device: str = "auto",
    on_progress: ProgressCb | None = None,
    on_cue: CueCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
) -> list[dict[str, Any]]:
    from ..runtime_extras import ensure_extras_for_models

    ensure_extras_for_models([asr_model], force=False, on_progress=on_progress)
    if not is_model_installed(asr_model):
        asr_dir = model_local_path(asr_model)
        missing = []
        for name in (
            "config.json",
            "preprocessor_config.json",
            "tokenizer_config.json",
            "tokenizer.json",
            "model.safetensors",
        ):
            p = asr_dir / name
            if not p.is_file() or p.stat().st_size < 64:
                missing.append(name)
        hint = (
            f"缺少文件: {', '.join(missing)}。"
            if missing
            else ""
        )
        raise RuntimeError(
            f"ASR model not installed or incomplete: {asr_model}. {hint}"
            "请在模型列表对 Cohere Transcribe 使用「强制重新下载」"
            "（需已填写 Hugging Face Token，建议官方端点）。"
        )
    asr_dir = model_local_path(asr_model)
    lang = _map_language(language)

    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 8,
                "detail": f"加载 Cohere Transcribe（{lang}）…",
            }
        )
    processor, model = _get_asr_bundle(asr_dir, device)
    duration_s = _probe_duration_s(media_path)
    if duration_s <= 0:
        raise RuntimeError(
            f"无法读取媒体时长（{media_path}），Cohere Transcribe 不能安全开窗。"
            "请确认 ffmpeg/ffprobe 可用后重试。"
        )
    windows = _windows(duration_s)

    from ..audio.preprocess import stage_media_for_long_asr, touch_path, trim_media_window

    work = Path(tempfile.mkdtemp(prefix="cohere_asr_"))
    all_cues: list[dict[str, Any]] = []
    fail_count = 0
    try:
        # Own a stable path for the full-film denoise/source wav (long jobs).
        staged = stage_media_for_long_asr(media_path, work)
        for i, (start, end) in enumerate(windows):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            if on_progress:
                local = asr_local_from_timeline(
                    processed_s=start,
                    duration_s=duration_s,
                    start=12.0,
                    end=92.0,
                )
                detail = f"{format_mmss(start)} / {format_mmss(duration_s)} · Cohere"
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": detail,
                        "processedSec": float(start),
                        "mediaDurationSec": duration_s,
                    }
                )
            if i % 10 == 0:
                touch_path(staged)
            try:
                wav = trim_media_window(
                    staged,
                    start_sec=start,
                    end_sec=end,
                    out_dir=work / f"w{i:04d}",
                )
            except Exception as err:
                fail_count += 1
                _log.warning("Cohere trim %s-%s failed: %s", start, end, err)
                if "不存在" in str(err) or "No such file" in str(err):
                    raise RuntimeError(
                        f"长片转写中途丢失输入音频（{staged}）。"
                        "请关闭对 temp/engine-work 的自动清理后重试；"
                        "也可关掉「轻度降噪」再跑。"
                        f" 详情: {err}"
                    ) from err
                continue
            try:
                text = _transcribe_window(
                    processor,
                    model,
                    wav,
                    language=lang,
                )
            except Exception as err:
                fail_count += 1
                _log.warning("Cohere window %s-%s failed: %s", start, end, err)
                continue
            if not text:
                continue
            span_end = start + max(0.5, (end - start) * 0.95)
            part = _distribute_text_cues(text, start=start, end=span_end)
            for cue in part:
                if on_cue:
                    on_cue(cue)
                all_cues.append(cue)
    finally:
        shutil.rmtree(work, ignore_errors=True)

    n_win = max(1, len(windows))
    if fail_count and (fail_count >= (n_win + 1) // 2 or not all_cues):
        raise RuntimeError(
            f"Cohere Transcribe failed {fail_count}/{n_win} windows "
            f"({Path(media_path).name}); aborting partial transcript"
        )

    all_cues.sort(key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)))
    cleaned: list[dict[str, Any]] = []
    for cue in all_cues:
        text = str(cue.get("text") or "").strip()
        if not text:
            continue
        item = dict(cue)
        if cleaned and float(item["start"]) < float(cleaned[-1]["end"]) - 0.05:
            item["start"] = float(cleaned[-1]["end"])
            if float(item["end"]) <= float(item["start"]):
                item["end"] = float(item["start"]) + 0.25
        cleaned.append(item)

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(cleaned)} 条（Cohere Transcribe）",
                "processedSec": duration_s,
                "mediaDurationSec": duration_s,
            }
        )
    return cleaned
